interface User {
  name: string
  email: string
}

async function getUserProfile() {
  try {
    const res = await fetch('/api/users/profile')
    return res.json()
  } catch {
    return { name: 'Unknown User', email: 'unknown@example.com' }
  }
}

export default async function UserProfile() {
  const user: User = await getUserProfile()

  return (
    <div>
      <h2>User Profile</h2>
      <div>{user.name}</div>
      <div>{user.email}</div>
    </div>
  )
}
